import{_ as s}from"./chunks/05-terminal.BgHtxeE4.js";import{_ as t,a}from"./chunks/05d-terminal-session.B-dA9tke.js";import{_ as i,o as n,c as r,a2 as o}from"./chunks/framework.DUZafPzB.js";const b=JSON.parse('{"title":"Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"features/terminal.md","filePath":"features/terminal.md","lastUpdated":1791422495000}'),l={name:"features/terminal.md"};function h(p,e,d,c,g,u){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h1><p>Optional: open an interactive shell on the Agent host from the browser. <strong>Not sandboxed</strong> — anything that OS user can do is possible. Enable only in trusted environments.</p><p><img src="'+s+'" alt="Terminal: waiting for TOTP"></p><p><img src="'+t+'" alt="Enter 6-digit code"></p><p><img src="'+a+`" alt="Session open with commands"></p><h2 id="enable-2fa-on-the-agent-host" tabindex="-1">Enable 2FA (on the Agent host) <a class="header-anchor" href="#enable-2fa-on-the-agent-host" aria-label="Permalink to &quot;Enable 2FA (on the Agent host)&quot;">​</a></h2><p>The secret stays on the Agent; the Hub <strong>only forwards</strong> codes for local verification and never stores the TOTP secret.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or with an explicit config:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup-terminal-2fa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/agent.toml</span></span></code></pre></div><p>Follow the wizard into your Authenticator app, then <strong>restart the Agent</strong>.</p><p>Or use an environment variable (automation-friendly; env wins; invalid values fail startup instead of silently disabling):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FILEBOX_AGENT_TERMINAL_TOTP_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BASE32SECRET……&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # ≥16 bytes after decode</span></span></code></pre></div><h2 id="open-resume-a-session" tabindex="-1">Open / resume a session <a class="header-anchor" href="#open-resume-a-session" aria-label="Permalink to &quot;Open / resume a session&quot;">​</a></h2><ol><li>Sidebar <strong>Terminal</strong>.</li><li>Enter the current 6-digit TOTP → <strong>Open terminal</strong> (or Resume).</li><li>Every open / resume needs a <strong>fresh</strong> code; reused codes are rejected until the next 30s window.</li><li><strong>Sessions</strong> supports Refresh, Resume, End.</li><li><strong>New session</strong> opens another shell.</li></ol><h2 id="session-lifecycle" tabindex="-1">Session lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to &quot;Session lifecycle&quot;">​</a></h2><ul><li>After browse navigation, disconnects, Hub restarts, or idle time, shells can still <strong>Resume</strong>.</li><li><strong>Agent process restart</strong> drops sessions; about <strong>256 KiB</strong> of recent output is replayed.</li><li>Browser logout detaches but the shell can keep running until End or Agent restart.</li></ul><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>Terminal power equals that OS user’s privileges on the Agent host.</li><li>Do not enable on shared or untrusted machines.</li><li>Prefer upgrading Hub / Agent / frontend major versions together (see release notes).</li></ul><p>Related: <a href="./security">Security &amp; sensitive files</a> · <a href="/filebox/ops/agent">Agent ops</a></p>`,18)])])}const y=i(l,[["render",h]]);export{b as __pageData,y as default};
